"use client"

export default function Home() {

  const prompt = "Use this spotify data and the responses to this questionaire to generate a playlist of the proper length and proper 'vibe' for this skater."

  const [output, setOutput] = useState('This is a nextjs project')
  
  const generateText = async () => {
    try {
      const response = await fetch('/api/generate',{
        method: 'POST',
        headers: {
          'Content-type':'application/json'
        },
        body:JSON.stringify({body:prompt})
      });

      const data = await response.json()

      if (response.ok) {
        setOutput(data.output)
      }else {
        setOutput(data.error)
      }
    } catch(error) {
      console.error(error)
    }
  }
  return (
    <div className="font-sans grid grid-rows-[20px_1fr_20px] items-center justify-items-center min-h-screen p-8 pb-20 gap-16 sm:p-20">

    </div>
  );
}
